from sympy import isprime
sols = []
for p in range(2, 60):
    if not isprime(p): continue
    for n in range(1, 2*p+1):
        if ((pow(p-1, n) + 1) % pow(n, p-1)) == 0:
            sols.append((n,p))
print(sols)
